'use strict';
(()=>{
const sections=[['home','Trang bìa','Bắt đầu hành trình'],['about','Giới thiệu đề tài','Mục tiêu & nơi ứng dụng'],['prompts','80 câu lệnh AI','Tìm, lọc & sao chép'],['builder','Cá nhân hóa kế hoạch','Bối cảnh lớp học của tôi'],['guide','Hướng dẫn từng bước','Từ câu lệnh đến bản dự thảo'],['lessons','Kho bài dạy mẫu','Hoạt động & học liệu'],['checklist','Kiểm tra kế hoạch','Giáo viên rà soát'],['resources','Tài liệu tải xuống','PDF, Word & câu lệnh']];
const stage=document.getElementById('book-stage'),leaf=document.getElementById('book-leaf');let current='home',busy=false,lastPage=null;
function escape(s){return String(s).replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]))}
function list(){return sections.map(([id,title,sub],i)=>`<a href="#${id}" data-page="${id}"><span>${i===0?'BÌA':String(i).padStart(2,'0')}</span><div><b>${title}</b><small>${sub}</small></div></a>`).join('')}
document.getElementById('book-contents').innerHTML=list();
function turn(hash){if(busy||!hash||hash===location.hash)return;if(matchMedia('(prefers-reduced-motion: reduce)').matches){location.hash=hash;return}busy=true;const nextId=hash.slice(1).split('/')[0];const oldIndex=sections.findIndex(s=>s[0]===current),nextIndex=sections.findIndex(s=>s[0]===nextId);const back=nextIndex>=0&&nextIndex<oldIndex;const sheet=document.getElementById('page-turn-sheet');sheet.innerHTML=`<span class="turn-sheet-mark">SỔ TAY ĐIỆN TỬ <b>AI</b></span><span class="turn-sheet-title">${escape(sections[Math.max(0,nextIndex)]?.[1]||'Nội dung sổ tay')}</span><span class="turn-sheet-lines"></span>`;leaf.classList.remove('turn-forward','turn-back');void leaf.offsetWidth;leaf.classList.add(back?'turn-back':'turn-forward');setTimeout(()=>{location.hash=hash},230);setTimeout(()=>{leaf.classList.remove('turn-forward','turn-back');busy=false},680)}
function rendered(page){current=page==='lesson'?'lessons':page;const admin=page==='admin';stage.classList.toggle('is-cover',page==='home');stage.classList.toggle('is-admin',admin);document.body.classList.toggle('admin-mode',admin);const n=sections.findIndex(s=>s[0]===current);const i=n<0?0:n;document.getElementById('book-section-title').textContent=admin?'Quản trị thông tin đề tài':sections[i][1];document.getElementById('book-folio').textContent=admin?'Bản quản trị demo':i===0?'TRANG BÌA':`CHƯƠNG ${String(i).padStart(2,'0')} / 07`;document.getElementById('book-page-position').textContent=admin?'Thông tin lưu trên trình duyệt':`${i+1} / ${sections.length}`;const prev=document.getElementById('book-prev'),next=document.getElementById('book-next');prev.disabled=i===0||admin;next.disabled=i===sections.length-1||admin;prev.dataset.target=i>0?sections[i-1][0]:'';next.dataset.target=i<sections.length-1?sections[i+1][0]:'';next.querySelector('span').textContent=i===0?'Mở sổ tay':'Trang tiếp';document.querySelectorAll('#book-contents [data-page]').forEach(a=>{const on=a.dataset.page===current;a.classList.toggle('active',on);if(on)a.setAttribute('aria-current','page');else a.removeAttribute('aria-current')});const main=document.getElementById('main');if(lastPage!==page)main.scrollTop=0;lastPage=page;const product=window.RESEARCH_CONFIG.get().productTitle;document.querySelectorAll('[data-research-product]').forEach(el=>{el.textContent=product});document.querySelector('#site-description')?.setAttribute('content',product+' — sổ tay điện tử và thư viện 80 câu lệnh AI.');}
document.addEventListener('click',e=>{const nav=e.target.closest('a[href^="#"]');if(nav&&!e.defaultPrevented&&!e.ctrlKey&&!e.metaKey&&!e.shiftKey&&nav.getAttribute('href')!=='#main'&&!nav.getAttribute('href').includes('admin')&&current!=='admin'){const href=nav.getAttribute('href');if(href!==location.hash){e.preventDefault();turn(href)}}const btn=e.target.closest('[data-book-turn]');if(btn&&!btn.disabled)turn('#'+btn.dataset.target)});
document.addEventListener('keydown',e=>{if(e.altKey||e.ctrlKey||e.metaKey||e.shiftKey||e.target.closest('input,textarea,select,button,a,[contenteditable]')||document.querySelector('dialog[open]'))return;if(e.key==='ArrowRight'){const n=document.getElementById('book-next');if(!n.disabled){e.preventDefault();turn('#'+n.dataset.target)}}if(e.key==='ArrowLeft'){const p=document.getElementById('book-prev');if(!p.disabled){e.preventDefault();turn('#'+p.dataset.target)}}});
window.Handbook={rendered,turn};
})();
